            parts = listOf(
                StoryPart(1, "A Button in a Box", listOf("A teacher brought a small box of everyday objects to class: a button, a bus ticket, a pencil stub, and a smooth stone.", "Students were invited to imagine what each object might have seen, then separate their inventions from any real history.", "Mariam wondered whether the school could create a museum of ordinary things.")),
                StoryPart(2, "The First Donation", listOf("The librarian suggested that every object needed a clear donor record and permission before display.", "A caretaker donated a retired hall pass and explained how it had been used to organise school events.", "The class wrote down the story in the caretaker's own words.")),
                StoryPart(3, "A Story with Limits", listOf("A student guessed that an old ticket came from a famous event, but no date or venue was visible.", "The teacher explained that a museum should not turn guesses into facts.", "The class labelled it 'origin unknown' until a reliable source could be found.")),
                StoryPart(4, "The Donor's Visit", listOf("A former pupil recognised the ticket and identified the local bus company from its old design.", "The archive confirmed the approximate period, but could not verify the journey.", "The class recorded what was known and kept the rest as an open question.")),
                StoryPart(5, "A Travelling Display", listOf("The school approved a small display that could move between classrooms.", "Students selected objects that were safe to handle and used copies or photographs for fragile items.", "Each label included the donor's approved story and the source of any verified date.")),
