                StoryPart(7, "The Museum Map", listOf("Students created a simple map showing where each object had come from, using broad locations rather than private addresses.", "The teacher checked that no personal details were exposed.", "The map helped visitors see how ordinary objects connected different parts of the school community.")),
                StoryPart(8, "A Visitor's Memory", listOf("A parent recognised the retired hall pass and shared a memory of a school concert.", "The class asked whether the parent wished to contribute and let them approve the final wording.", "The object gained another chapter without losing its original donor story.")),
